window.__APP_CHUNKS=window.__APP_CHUNKS||[];window.__APP_CHUNKS[8]="\", \"targets\": [\"Судак\", \"Щука\", \"другой хищник\"], \"facts\": [\"На поролон с чебурашкой 12 г было два хищных контакта.\", \"Берег высокий; подъём рыбы неудобен.\", \"Течение и доступ к глубине делают участок интересным для донного хищника.\"], \"hypothesis\": \"Рыба может стоять глубже доступной береговой полки; отводной и более тяжёлый контроль дна перспективнее перебора цветов.\", \"next\": \"Проверять структуру и дальние бровки, а не менять приманки на одном месте.\"}, {\"name\": \"Вах / Излучинск\", \"region\": \"ХМАО — Югра\", \"coords\": \"60.950311, 76.901621 / 60.954234, 76.892085\", \"status\": \"Отрицательная разведка\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Хищник\"], \"facts\": [\"Песчаный мелководный берег.\", \"10 г позволяли контролировать дно.\", \"Несколько микроучастков были проверены без поклёвок.\"], \"hypothesis\": \"Доступная полка в тот день была пустой; хищник мог стоять дальше или глубже.\", \"next\": \"Возвращаться только при новом основании: изменение воды, уровня, ветра или найденная структура.\"}, {\"name\": \"Ахтубинск — рабочий участок\", \"region\": \"Астраханская область\", \"coords\": \"48.265990, 46.145411\", \"status\": \"Эталонный успех\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Окунь\", \"Жерех\"], \"facts\": [\"Июль 2021: ловля с лодкой, стоя по пояс в воде.\", \"Мелководье, заметное течение, сплошной ракушечник.\", \"Окунь — почти на каждом забросе; отдельные экземпляры около 1 кг.\", \"Жерех стоял дальше; требовался дальний заброс.\", \"Работали небольшие тонущие шумные VIB/раттлины.\"], \"hypothesis\": \"Сочетание ракушечника, течения и кормовой активности создавало локальную зону питания; чайки и бой были сильным полевым индикатором.\", \"next\": \"При повторе сначала искать ракушку + бой + чаек, а не точное старое место.\"}, {\"name\": \"Заволжское / Митинка / ерик Казачий\", \"region\": \"Астраханская область\", \"coords\": \"точные точки ещё не внесены\", \"status\": \"Большая личная серия\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Судак\", \"Щука\", \"Окунь\", \"Жерех\", \"Буффало\"], \"facts\": [\"05–11.08.2021 — хорошая рыбалка по судаку, щуке и окуню.\", \"27.07–03.08.2022 — снова хорошо, но состав и активность отличались.\", \"27.09–01.10.2023 — практически ноль теми же основными методами.\", \"Ерик Казачий: живец на отводном давал судака; одна из лучших личных схем.\", \"В 2022 на прикормленной точке был необычно сильный утренний выход буффало.\"], \"hypothesis\": \"Главное направление исследования — сравнить гидрологию и температуру 2021/2022 с неудачным 2023, а не списывать всё на календарный месяц.\", \"next\": \"Добавить точные точки и поднять архив уровней/расходов по датам.\"}, {\"name\": \"Красный Яр / Маячная / Кривой Бузан\", \"region\": \"Астраханская область\", \"coords\": \"точные точки требуют восстановления\", \"status\": \"Контрастные сезоны\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Щука\", \"Судак\", \"Жерех\", \"Мирная рыба\"], \"facts\": [\"Начало октября 2022 — хороший результат.\", \"Конец мая 2023 — очень высокая вода и сильное течение, практически ноль.\", \"Август 2024 — те же места и широкие методы, но заметно хуже 2022.\", \"На Маячной работали мирные снасти; по хищнику — воблеры, VIB и живец на отводном.\"], \"hypothesis\": \"2023 выглядит как отрицательный пример экстремальной гидрологии, а не как доказательство «май не работает».\", \"next\": \"Связать поездки с уровнями/расходом и температурой воды.\"}, {\"name\": \"Астрахань — городская береговая точка\", \"region\": \"Астраханская область\", \"coords\": \"46.398523, 48.040125\", \"status\": \"Личный успех\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Щука\"], \"facts\": [\"Поздний август 2021, раннее утро.\", \"Около 7 небольших щук примерно за 3 часа.\", \"Работали VIB/раттлины.\", \"Видимой растительности не было; клёв держался всё время до ухода.\"], \"hypothesis\": \"Участок мог работать как линейная кормовая дорожка без явной травы.\", \"next\": \"Уточнить водоём/рукав по карте и восстановить точную дату.\"}, {\"name\": \"Избербаш — Каспийский берег\", \"region\": \"Дагестан\", \"coords\": \"42.598532, 47.860646\", \"status\": \"Сильный контраст\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Кутум\", \"Вобла / другие карповые\"], \"facts\": [\"22–23.08.2020 — очень сильный кратковременный клёв; много кутума и воблы.\", \"Берег каменисто-песчаный; заброс требовался за крупные выступающие камни.\", \"5–7.10.2025 на той же точке было заметно хуже.\"], \"hypothesis\": \"В 2020 штормовая обстановка и волна могли концентрировать корм и рыбу у каменисто-песчаной кромки.\", \"next\": \"Сопоставить 21–24.08.2020 и 05–07.10.2025: ветер, волна, SST, давление и осадки.\"}, {\"name\": \"Сулак / район Нечаевки\", \"region\": \"Дагестан\", \"coords\": \"точная точка ещё не закреплена\", \"status\": \"Неудачная разведка\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Щука\"], \"facts\": [\"05–11.10.2025: высокая вода, очень сильное течение, серая водная масса.\", \"Поклёвок не было.\", \"Местный рыбак говорил о щуке и весеннем сезоне, но сам ушёл, увидев состояние воды.\"], \"hypothesis\": \"Ключевой фактор — не октябрь как таковой, а гидрология и режим сбросов.\", \"next\": \"Реконструировать уровни/расход и работу гидроузлов на даты поездки.\"}], \"methods\": [{\"name\": \"VIB / раттлины\", \"level\": \"Личная сильная практика\", \"image\": \"data:image/webp;base64,\", \"where\": \"Карьер ГРЭС, Ахтубинск, Заволжское, Астрахань\", \"evidence\": \"На карьере ГРЭС все 4 щуки пришли только на VIB. В Ахтубинске небольшие шумные VIB дали серию окуня и жереха; в Астрахани городская точка дала серию щук.\", \"setup\": \"Тонущая приманка; вести у дна или немного выше. На карьере сработала равномерная проводка с рывками.\", \"develop\": \"Собрать классификацию по размеру, массе, глубине, шумности и типу падения.\"}, {\"name\": \"Живец на отводном поводке\", \"level\": \"Личный фирменный метод\", \"image\": \"data:image/webp;base64,";